package br.com.bancohorizonte.repository; import br.com.bancohorizonte.entity.Pessoa; import jakarta.persistence.*; import java.util.*;
public class PessoaRepository { private final EntityManager em; public PessoaRepository(EntityManager em){this.em=em;} public void salvar(Pessoa pessoa){em.persist(pessoa);} public Optional<Pessoa> porId(Long id){return Optional.ofNullable(em.find(Pessoa.class,id));} public boolean existeCpf(String cpf){TypedQuery<Long> q=em.createQuery("select count(p) from Pessoa p where p.cpf = :cpf",Long.class);return q.setParameter("cpf",cpf).getSingleResult()>0;} }
